{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C11", "C20", "C33", "C08", "C12", "C21", "C31", "C35", "C36", "C01", "C16"],
  "contradictory_card_ids": ["C25", "C52", "C53", "C54", "C55", "C57", "C58", "C60"],
  "prediction_basis_card_ids": ["C11", "C20", "C33", "C08", "C12", "C35", "C36", "C01", "C16"],
  "claims": [
    {
      "claim": "Zeaxanthin, a highly lipophilic polyene, is reported as highly bioavailable when ingested with fat and bioavailable from food matrices, supporting that lipophilic polyenes can achieve meaningful oral absorption despite poor solubility.",
      "card_ids": ["C11", "C20", "C33"]
    },
    {
      "claim": "Leflunomide and teriflunomide, N-aryl amide drugs, show oral bioavailability of approximately 80-100% in humans, supporting that anilide-containing lipophilic drugs can exceed the 20% threshold.",
      "card_ids": ["C08", "C12", "C21", "C31", "C35", "C36"]
    },
    {
      "claim": "Desvenlafaxine, a phenol-containing drug, has absolute oral bioavailability of about 80%, showing that a phenolic group does not preclude F >= 20%.",
      "card_ids": ["C01", "C16"]
    },
    {
      "claim": "L4 solubility records show very poor aqueous solubility/dissolution for lutein, lycopene, and astaxanthin, while tretinoin shows high solubility in surfactants; this indicates a solubility liability for the query but is formulation-dependent and not a direct F measurement.",
      "card_ids": ["C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60"]
    },
    {
      "claim": "The apatinib L2 record of 10-20% bioavailability is structurally distant and low-transferability; it does not affirmatively establish F < 20% for the query.",
      "card_ids": ["C07", "C25"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query retinoid amide is supplied.",
    "No matched oral-versus-IV exposure data or IV comparator for the query is available.",
    "No query-specific solubility or dissolution measurement; L4 records are for reference carotenoids/retinoids and transfer is qualitative.",
    "No permeability, first-pass metabolism, or efflux data for the query.",
    "Formulation and fed/fasted status are unspecified; solubility limitations may be overcome by food or lipid-based formulations.",
    "Dose is unknown; solubility-limited absorption is dose-dependent."
  ],
  "decision_summary": "L4 solubility/dissolution records for related carotenoids and retinoids add a measurable solubility liability for the highly lipophilic, neutral query, weakening but not overturning the prior high prediction. The high-F anilide and phenol contexts and the food-dependent zeaxanthin bioavailability still make F >= 20% better supported than F < 20%, but with low confidence."
}

